window.FINAL_REVIEW=[{"chapter": 101, "index": 0, "title": "Bulutun tanımı ve 5 temel özellik", "rows": [["Bulut bilişim", "İşlem, ağ, depolama ve uygulama kaynaklarına ortak havuzdan, ağ üzerinden, isteğe bağlı ve az yönetim çabasıyla erişme modelidir. Arkada gerçek sunucular ve veri merkezleri vardır."], ["İsteğe bağlı kendi kendine hizmet", "Kaynakları sağlayıcının personelini beklemeden panel/API ile açıp kapatma."], ["Geniş ağ erişimi", "Standart ağ yöntemleriyle farklı cihaz ve istemcilerden erişme; yalnız halka açık internetle sınırlı değildir."], ["Ortak kaynak havuzu", "Kaynakları müşteriler arasında talebe göre tahsis etme; müşteri verileri ve erişimleri ayrılır."], ["Hızlı esneklik", "Kaynağı talebe göre artırıp azaltma. Ölçülebilir hizmet ise tüketimi izleme, denetleme ve raporlamadır."], ["Ödeme", "Kullanıma, tahsise veya aboneliğe göre ücret olabilir. Ölçülebilirlik bütün hizmetlerin aynı faturalandığı anlamına gelmez."]], "remember": "5 özellik + 3 hizmet modeli + 4 dağıtım modeli. Bunlar farklı sınıflandırmalardır.", "vize": true, "details": [], "id": "review-101-0"}, {"chapter": 101, "index": 1, "title": "Gelişim sırası ve öncü kavramlar", "rows": [["Dersin gelişim sırası", "Ana bilgisayar → kişisel bilgisayar → bilgisayar ağları → internet. Gerçek tarihsel gelişmeler örtüşür; bu dersin basitleştirilmiş dizisidir."], ["Buluta geçişi hazırlayanlar", "Zaman paylaşımı, sanallaştırma, geniş bant, ucuz/güçlü işlemciler, otomasyon ve büyük veri merkezleri; yatırım, bakım, enerji ve personel maliyetleri."], ["Grid / utility / hosting", "Grid farklı kaynakları ortak işte birleştirir. Utility tüketim esaslı bilişim hizmeti fikridir. Hosting uygulamayı başka ortamda barındırır; her hosting tam bir bulut değildir."], ["Önemli duraklar", "1960’lar McCarthy ve zaman paylaşımı; 1969 ARPANET/Licklider; 1970 sanallaştırma; 1991 WWW; 1997 Chellappa; 1999 Salesforce; 2006 Amazon EC2/S3."], ["IoT ve mobil ağlar", "Nesneler, telefonlar ve sensörler veri üretir; hızlı bağlantılar uzaktan işlem, saklama ve paylaşımı yaygınlaştırır."]], "remember": "Amazon, çalışma notlarının öncü hizmet örneğidir; bulut fikrinin bütün tarihini 2006’da başlatma.", "vize": true, "details": [["Eski pazar tahminleri", "Notta 2013 için £78 milyar/%18,5 artış; 2014 için £103,8 milyar/%20 artış geçer. Bunlar güncel istatistik değildir."]], "id": "review-101-1"}, {"chapter": 101, "index": 2, "title": "Özellikler, önem ve ekonomik etkiler", "rows": [["Dokuz uygulamalı özellik", "Kişiselleştirme; paylaşım/iş birliği; ayarlanabilir kapasite; erişim kolaylığı; düşük maliyet potansiyeli; esneklik/verimlilik; esnek ödeme; güvenlik; çevresel fayda."], ["Ekonomik etki", "Başlangıç yatırımını azaltma, atıl kapasiteyi düşürme, üretkenliği ve işe odaklanmayı artırma. Tasarruf iş yüküne ve kaynak yönetimine bağlıdır."], ["Çevresel etki", "Ortak ve verimli donanım kullanımı enerji/karbon giderini azaltabilir; sonuç enerji kaynağına ve veri merkezi verimine bağlıdır."], ["Veri ve erişim", "Artan veri hacmi, farklı cihazlardan erişim, ortak çalışma ve hızlı geliştirme buluta ihtiyacı büyütür."], ["Notlardaki oranlar", "Maliyetin düşeceğini öngörenler %57; enerji tasarrufu %60’a kadar; karbon salımında yaklaşık %35 azalma örnekleri. Her kurum için garanti değildir."]], "remember": "Güvenlik bir kazanım da risk de olabilir; sonuç sağlayıcı, mimari ve doğru ayarların ortak ürünüdür.", "vize": true, "details": [], "id": "review-101-2"}, {"chapter": 101, "index": 3, "title": "Bilişim sistemi, kullanım alanları ve Türkiye", "rows": [["Temel tanımlar", "Teknoloji bilimsel bilginin uygulanmasıdır. Bilişim teknolojileri bilgisayar ve iletişimle veri toplama/işleme/saklama/iletmeyi destekler. Bilişim sistemi bunları kurumsal amaçlarla birleştirir."], ["Beş bileşen", "Donanım + yazılım + veri + insan + süreç. İlk üçü teknoloji boyutu; insan ve süreç gerçek işleyişi tamamlar."], ["Kullanım alanları", "Eğlence: film/oyun; eğitim: EBA/uzaktan ders; ulaşım: navigasyon/bilet; sağlık: MHRS/giyilebilir cihaz; iletişim: toplantı/e-posta; bankacılık: ATM/e-ticaret; mühendislik: 3B model/simülasyon."], ["Türkiye için nottaki güçlü yönler", "Coğrafi konum, genç nüfus, kültürel birikim, bankacılık ve e-devlet deneyimi."], ["Nottaki zayıf yönler", "Yetki/koordinasyon, finansman, dar pazar, marka algısı ve güçlü marka eksikliği, nitelikli eleman/eğitim açığı. Bunlar dönemsel değerlendirmelerdir."], ["Uygulama grupları", "Ticari/e-ticaret, sağlık, eğitim, eğlence-hobi ve mobil. Mobil bulut cihazın sınırlı işlem/depolamasını uzak kaynaklarla destekler; ağ ve enerji maliyeti de vardır."]], "remember": "Bilişim sistemi yalnız bilgisayar değildir: insan ve süreç de sistemin parçasıdır.", "vize": true, "details": [], "id": "review-101-3"}, {"chapter": 101, "index": 4, "title": "Bulutun 10 temel faydası", "rows": [["Maliyet ve zaman", "Donanım yatırımı/enerji/bakım azalabilir; kaynak temini hızlanır; yazılım kurulumu, lisanslama ve sürüm yönetimi kolaylaşabilir. Ücretler tamamen yok olmaz."], ["Esneklik ve uyumluluk", "Yoğun dönemde kapasite artırıp sakin dönemde azaltma; gereken platforma erişme. Sonuç açıklama günü gibi ani yükler ve ay sonu muhasebe yoğunluğu esnekliği örnekler."], ["Güvenlik ve yönetilebilirlik", "Uzman ekip, merkezî güncelleme, izleme ve standart işletimden yararlanma. Veri ve yetki ayarlarında müşteri görevi sürer."], ["Erişim ve iş birliği", "Konumdan/cihazdan bağımsız uygun erişim; ortak belgenin güncel sürümünde çalışma."], ["Stratejik hız ve tasarruf", "Ürünü hızlı çıkarma, ana işe odaklanma; sermaye yatırımının bir kısmını hizmet giderine dönüştürme."], ["SLA ve felaket kurtarma", "SLA hizmet seviyesinin koşullarını tanımlar. Disaster Recovery afet sonrası geri dönme hazırlığıdır; afetin hiç olmayacağı garantisi değildir."]], "remember": "10’lu liste: donanım maliyeti, zaman, yazılım maliyeti, esneklik, uyumluluk, güvenlik/güncelleme, yönetilebilirlik, erişim/iş birliği, stratejik hız, tasarruf.", "vize": true, "details": [], "id": "review-101-4"}, {"chapter": 101, "index": 5, "title": "Bulutun riskleri ve sınırlamaları", "rows": [["Güvenlik/gizlilik", "Yetkisiz erişim, veri sızıntısı, yazılım açığı, kiracı izolasyonu, veri konumu ve kullanım koşulları."], ["Güncelleme ve sağlayıcı", "Sürüm/platform değişikliği uyumsuzluk yaratabilir. Sağlayıcının uzmanlığı, mali dayanıklılığı ve personeli değerlendirilir."], ["Kesinti ve performans", "Planlı bakım veya plansız arıza; bant genişliği, gecikme, yoğun sunucu ve kötü sorgu performansı etkiler. İstemcinin internetinin hızlı olması tek başına yeterli değildir."], ["Satıcı kilidi ve sınırlı kontrol", "Özel API, veri biçimi ve bağımlılıklar taşınmayı zorlaştırır. Fiziksel altyapı ile bazı yazılım katmanları sağlayıcının yönetimindedir."], ["Lisanslama", "Makine/işlemci/kurulum sayısına bağlı lisanslar otomatik oluşup silinen VM’lerde maliyet ve uyum sorunu yaratabilir."], ["Çerçeve ve belgeler", "ITIL/COBIT yönetim çerçeveleri; ISO 9001, ISO 27001/27002, BS 25999 notlardaki standart örnekleri; CISSP, CEH, CISA, CCIE, GIAC personel sertifikası örnekleridir. Hepsi kanun değildir."]], "remember": "Risk listesi: güvenlik-gizlilik, güncellemeler, sağlayıcı/personel, kesinti, ağ-performans, satıcı kilidi, uygulama yavaşlığı, sınırlı kontrol, lisans.", "vize": true, "details": [], "id": "review-101-5"}, {"chapter": 102, "index": 0, "title": "Üç rol, panel ve API", "rows": [["Tüketici", "Hizmeti kullanan kişi/kuruluş; kaynak, abonelik ve erişimlerini yönetir."], ["Servis sağlayıcı", "Hizmeti kurar, işletir ve tüketiciye sunar; sözleşmedeki destek ve güvenlik görevlerini yerine getirir."], ["Servis geliştirici", "Temel hizmetlerle yeni uygulama oluşturur; yayımlama, izleme ve analitik yapar. Aynı kuruluş farklı ilişkilerde farklı roller üstlenebilir."], ["Panel / API", "Panel insanın kullanacağı arayüzdür. API yazılımların tanımlı kurallarla iletişim kurmasını ve otomasyonu sağlar."]], "remember": "Tüketici kullanır; sağlayıcı sunar; geliştirici çözüm üretir.", "vize": true, "details": [], "id": "review-102-0"}, {"chapter": 102, "index": 1, "title": "Ön uç, arka uç ve yapısal katmanlar", "rows": [["Front-end", "Kullanıcının eriştiği cihaz, istemci ve arayüz: PC, zengin/ince/sıfır istemci, tablet, telefon, tarayıcı veya sanal oturum."], ["Back-end", "Sunucular, VM’ler, depolama, veri tabanı, uygulama, güvenlik ve yönetim bileşenleri. Ön uçla ağ üzerinden haberleşir."], ["Beş katman", "Sunucu → altyapı → platform → uygulama → istemci. Fiziksel kaynaklardan kullanıcıya doğru ilerler."], ["Yük dengeleme", "İstekleri uygun sunuculara dağıtır. Yeni kapasite eklemekle aynı işlem değildir."], ["Sanallaştırma / yedekleme", "Sanallaştırma fiziksel kaynağı mantıksal ortamlara ayırır; yedekleme kayıp sonrası geri dönüş kopyası üretir."]], "remember": "Bir bulutun tek merkezî sunucuya dayanması veya her uygulamaya ayrı fiziksel sunucu vermesi zorunlu değildir.", "vize": true, "details": [], "id": "review-102-1"}, {"chapter": 102, "index": 2, "title": "Kurum içi altyapı ve toplam maliyet", "rows": [["Kurum içi BT", "Sunucu/depolamaya ek olarak UPS, jeneratör, soğutma, yangın sistemi, kamera, fiziksel erişim, izleme, yama, bakım ve uzak yedek gerekir."], ["Bulut yaklaşımı", "Bu yeteneklerin bir kısmına hizmet olarak erişilir; kendi sistem odası yatırımı azalabilir. Kurumun veri, uygulama, kullanıcı ve hizmet denetimi sürer."], ["Maliyet buzdağı", "Görünen lisans/abonelik yalnız bir parçadır. Özelleştirme, kurulum, donanım, BT personeli, bakım ve eğitim de toplam maliyete katılır."], ["Notun maliyet dağılımı", "Klasik: lisans %9, özelleştirme/uygulama %43, donanım %26, personel %14, bakım %7, eğitim %1. Bulut örneği: abonelik %68, uygulama/özelleştirme/eğitim %32."]], "remember": "%68 abonelik payıdır; “bulut %68 tasarruf sağlar” anlamına gelmez.", "vize": true, "details": [], "id": "review-102-2"}, {"chapter": 102, "index": 3, "title": "IaaS — altyapı hizmeti", "rows": [["Sunulan", "CPU, RAM, depolama, ağ ve sanal makine. Sağlayıcı fiziksel altyapı ve sanallaştırmayı işletir."], ["Müşteri yönetimi", "İşletim sistemi, ara yazılım, uygulama, yama ve ilgili ayarlar. VM’de Linux ve web sunucusunu kendin kurman IaaS örneğidir."], ["Kullanım", "Test/geliştirme, web barındırma, değişken depolama, yedek/kurtarma, yüksek performanslı hesaplama (HPC) ve büyük veri. EC2, GoGrid ve Rackspace ders örnekleridir."], ["Cluster / multi-tenant", "Cluster birden çok makinenin birlikte çalışmasıdır. Çok kiracılılık ortak altyapının müşterilere izolasyonla sunulmasıdır."], ["Kazanç ve bedel", "Hızlı tahsis, esneklik ve daha çok kontrol; buna karşı OS/uygulama yönetimi ve lisans sorumluluğu daha fazladır."]], "remember": "IaaS: altyapıyı alır, işletim sistemi ve üstünü sen yönetirsin.", "vize": true, "details": [], "id": "review-102-3"}, {"chapter": 102, "index": 4, "title": "PaaS — geliştirme ve çalıştırma platformu", "rows": [["Sunulan", "Yönetilen OS, çalışma zamanı, ara yazılım, geliştirme araçları ve tamamlayıcı hizmetler; sağlayıcı temel platformu işletir."], ["Müşterinin odağı", "Uygulama kodu, veri ve uygulama ayarları. Kodunu yükleyip temel sunucuyu kurmadan çalıştırma mantığıdır."], ["Üç kullanım alanı", "Geliştirme çerçevesi; analiz/iş zekâsı; tamamlayıcı hizmetler."], ["Yaşam döngüsü ve fayda", "Oluşturma → test → dağıtma → yönetme → güncelleme. Hazır bileşenler kod süresini azaltır; ekip çalışmasını ve çoklu istemci geliştirmeyi kolaylaştırır."], ["Örnek ve sınır", "Google App Engine. Desteklenen diller, çalışma ortamı ve sağlayıcı API’leri taşınabilirliği sınırlayabilir."]], "remember": "PaaS: uygulamanı geliştirirsin; temel çalışma platformunu sağlayıcı işletir.", "vize": true, "details": [], "id": "review-102-4"}, {"chapter": 102, "index": 5, "title": "SaaS, serverless ve sorumluluk sınırı", "rows": [["SaaS", "Hazır uygulamayı tarayıcı/istemciyle kullanırsın. Sağlayıcı uygulamanın işletimini ve alt katmanları yönetir; kullanıcı/veri/paylaşım kararlarında müşteri sorumluluğu devam eder."], ["Örnekler", "E-posta, takvim, ofis, belge yönetimi, CRM/MİY (müşteri ilişkileri yönetimi) ve ERP/KKP (kurumsal kaynak planlaması). Outlook/Hotmail/Yahoo Mail, Office 365 ve Google Fotoğraflar notun örnekleridir."], ["Kazanım", "Merkezî sürüm/bakım, farklı cihazdan erişim, altyapıyı tek tek kurmama. Tarayıcı kullanılması hizmetin ücretsiz veya her verinin yedekli olduğu anlamına gelmez."], ["Serverless", "Sunucu işletimi/tahsisi/ölçeklemesi geliştiriciden daha fazla soyutlanır; geliştirici iş mantığına odaklanır. Arkada sunucular yine vardır."], ["Ders tablosunun dili", "Şekil 2.16’da SaaS’ın tüm katmanları “Provider manages” gösterilir. Bu katman işletimi anlatımı, müşterinin hiçbir veri/erişim yetkisi olmadığı anlamına gelmez."]], "remember": "IaaS → PaaS → SaaS yönünde müşterinin altyapı işletim yükü azalır; veri ve erişim kararları tamamen ortadan kalkmaz.", "vize": true, "details": [], "id": "review-102-5"}, {"chapter": 102, "index": 6, "title": "Dört dağıtım modeli ve hibrit yapı", "rows": [["Genel / public", "Geniş müşteri kitlesine sağlayıcının altyapısından hizmet. Ortak donanım kullanılabilir; müşterinin dosyaları herkese açık olmaz."], ["Özel / private", "Tek kuruluşa ayrılmış kullanım. Kurum içinde/dışında barındırılabilir; kurum veya üçüncü taraf yönetebilir. Her kurum içi sunucu odası özel bulut sayılmaz."], ["Topluluk / community", "Ortak güvenlik, politika veya amaç taşıyan belirli kuruluşlar birlikte kullanır; örneğin ortak araştırma ortamı."], ["Hibrit / hybrid", "Ayrı bulut ortamlarının bütünleştirilmesi; derste çoğunlukla özel + genel. Talep artınca genel buluta açılma: cloud bursting."], ["Hibritin kuruluş yolları", "Farklı sağlayıcıları bütünleştirme; tek sağlayıcıdan hibrit paket alma; kendi özel bulutunu genel buluta bağlama. Veri, uygulama ve ağ taşınabilirliği tasarlanır."]], "remember": "Hizmet modeli sunulan katmanı; dağıtım modeli kullanım ve ortam düzenini tanımlar. Genel bulutta IaaS, özel bulutta PaaS olabilir.", "vize": true, "details": [], "id": "review-102-6"}, {"chapter": 102, "index": 7, "title": "Dosya depolama hizmetleri", "rows": [["Hizmet örnekleri", "iCloud: Apple hesabı/cihaz-fotoğraf eşitleme; Google Drive: dosya/belge saklama ve paylaşma; Dropbox ve Yandex.Disk: dosya saklama/paylaşma."], ["Eski ad", "SkyDrive, OneDrive’ın eski adıdır. Notta geçen kota, kampanya ve sürüm bilgileri güncel hizmet koşulu değildir."], ["Temel ayrım", "Depolama saklar; paylaşım erişim izni verir; senkronizasyon değişikliği eşitler; yedekleme geri dönüş kopyası tutar."], ["Fiziksel gerçeklik", "Uzak dosya yine fiziksel diskte tutulur. Uygun bağlantı ve yetki gerekir; yanlış silme eşitlenen cihazlara yayılabilir."]], "remember": "QEMU sanallaştırma/emülasyon aracıdır. Caspio ise veri tabanı/uygulama platformudur; bu adları dosya depolama hizmetleriyle aynı kategoriye koyma.", "vize": true, "details": [], "id": "review-102-7"}, {"chapter": 103, "index": 0, "title": "Sanal makine, hipervizör ve iki VM türü", "rows": [["Sanallaştırma", "Fiziksel kaynağı mantıksal ortamlara ayırıp donanımdan soyutlama. Kaynak verimini, izolasyonu ve hızlı ortam hazırlamayı destekler."], ["Sistem VM / proses VM", "Sistem VM kendi işletim sistemini çalıştırır. Proses VM tek programın yürütülme ortamıdır: Java → JVM; .NET → CLR."], ["Host / guest / hipervizör", "Host ev sahibi; guest konuk sistemdir. Hipervizör VM’leri çalıştırır ve CPU/RAM/disk/ağ kaynaklarını paylaştırır."], ["Tip 1", "Donanım → hipervizör → guest OS → uygulama. Bare-metal/native; VMware ESX ders örneğidir."], ["Tip 2", "Donanım → host OS → hipervizör → guest OS → uygulama. Hosted; VirtualBox, VMware Workstation, Parallels Desktop örnekleri."], ["WORA", "Write Once, Run Anywhere: Java bytecode’un uyumlu JVM bulunan farklı sistemlerde çalışabilmesi hedefi."]], "remember": "Sanallaştırma tek başına bulut değildir; bulutta self-servis, otomatik tahsis, ölçüm ve esneklik de bulunur.", "vize": true, "details": [], "id": "review-103-0"}, {"chapter": 103, "index": 1, "title": "Sanallaştırma araçları ve kazanımlar", "rows": [["Dersin açık kaynak listesi", "VirtualBox, Xen, Bochs, CoLinux, FAUmachine, Hercules emulator, KVM, LilyVM, QEMU, SheepShaver."], ["Dersin ticari/diğer ürün listesi", "VMware, Microsoft Virtual PC, VM/CMS, Parallels Workstation, vThere, Parallels Desktop for Mac, SVISTA, Trango, Virtual Iron Software. Bu tarihsel sınıflandırmadır."], ["Ayırt edici araç", "Daemon Tools disk/CD imajını sanal sürücü olarak bağlama örneğidir. Trango notta ticari grupta; Xen açık kaynak gruptadır."], ["Yararlar", "Sunucu birleştirme, hızlı VM oluşturma, test/geliştirme, daha az fiziksel donanım/enerji, merkezî izleme ve uyumlu host’a taşıma."], ["VMware notları", "1998 kuruluş, 1999 ilk ürünler; Workstation/GSX host OS üzerinde, ESX donanım üzerinde anlatılır. Sanal altyapı: sanallaştırma yönetimi + kaynak planlama + süreç otomasyonu."], ["Risk ve sayısal örnek", "Tek host arızası çok VM’yi etkileyebilir. %50 donanım/%80 operasyon tasarrufu ve CPU %10→%5 ifadeleri notun örnekleridir; evrensel sonuç değildir."]], "remember": "Yeni test ortamını hızlı oluşturmak sanallaştırma yararıdır; her VM için yeni fiziksel sunucu almak gerekmez.", "vize": true, "details": [], "id": "review-103-1"}, {"chapter": 103, "index": 2, "title": "Sanallaştırmanın dört uygulama türü", "rows": [["Donanım / sunucu", "Bir fiziksel sunucuda bağımsız işletim sistemleri ve mantıksal kaynaklar."], ["Oturum", "Terminal hizmetleriyle merkezî sunucudaki kullanıcı oturumuna/uygulamaya uzaktan erişim."], ["Masaüstü", "Kullanıcının uzaktaki sanal masaüstüne kendi bilgisayarı gibi bağlanması."], ["Uygulama", "Uygulamayı ve bağımlılıklarını OS’den soyutlama; dağıtım/sürüm yönetimi. Microsoft App-V ders örneğidir."]], "remember": "Sistem–proses ayrımı VM’nin kapsamı; Tip 1–Tip 2 ayrımı hipervizörün yeridir. Bu sınıflandırmaları birbirine karıştırma.", "vize": true, "details": [], "id": "review-103-2"}, {"chapter": 103, "index": 3, "title": "Günlük kullanım ve depolama ayrımları", "rows": [["Günlük işler", "E-posta/belge, web/blog barındırma, ses-video akışı, oyun/fotoğraf, yazılım dağıtımı, analiz; ayrıca veri saklama, yedekleme ve kurtarma."], ["Notun diğer hizmet adları", "Turkcell Akıllı Bulut, TTNET Bulut, Ubuntu One, iOmegaCloud, MobileMe; ayrıca Dropbox, Drive, iCloud, Yandex.Disk, SkyDrive/OneDrive. Bazıları eski ürün adlarıdır."], ["Eşitleme ve geri dönüş", "Senkronizasyon güncel durumları eşitler; replikasyon başka sistemde kopya sürdürür; sürümlü/ayrı yedek hatadan önceki duruma dönmeyi sağlar."], ["Marka ayrımı", "Apple iCloud ile Google Cloud farklı hizmetlerdir. PDF’de iCloud’un yanında verilen Google bağlantısı ürün eşleştirmesi değildir."]], "remember": "Farklı cihazdan erişim kolaylığı, yanlış silmeye karşı otomatik yedek garantisi değildir.", "vize": true, "details": [], "id": "review-103-3"}, {"chapter": 103, "index": 4, "title": "Büyük veri ve veri yapıları", "rows": [["Büyük veri", "Miktarı, hızı veya çeşitliliği nedeniyle alışılmış yöntemlerle yönetimi/işlenmesi güçleşen veri. Sabit bir TB eşiği veya yalnızca analiz edilmiş sonuç değildir."], ["Yapısal", "Tanımlı alan ve şema: öğrenci-not tablosu, finans işlemi."], ["Yarı yapısal", "Alan/etiket/hiyerarşi taşır; XML ve JSON. Tek sabit ilişkisel tablo şeması zorunlu değildir."], ["Yapısal olmayan", "Serbest metin, fotoğraf, ses, video; içeriği doğrudan sabit sütunlara oturmaz. Yine dosya biçimi vardır."], ["Tarih ve örnek", "Notta Cox/Ellsworth’un 1997’de bellek-disk kapasitesini aşan veri çalışması ve Diebold anılır. Çağrı kaydının tarih/süresi yapısal, konuşma içeriği serbest olabilir."]], "remember": "Bir verinin sensörden gelmesi tek başına yapısını belirlemez; kaydın biçimine bak.", "vize": false, "details": [], "id": "review-103-4"}, {"chapter": 103, "index": 5, "title": "5V ve veri analiz zinciri", "rows": [["Variety / çeşitlilik", "Farklı kaynak ve yapılar: tablo + metin + görüntü + sensör."], ["Velocity / hız", "Verinin üretilme, gelme ve işlenme hızına zamanında yanıt verebilme."], ["Volume / hacim", "Depolanıp işlenecek miktar."], ["Veracity / güvenilirlik", "Doğruluk, eksik/tutarsız kayıt, gürültü, yanlılık ve belirsizlik. Doğrulama/temizleme ve çapraz denetim gerekir."], ["Value / değer", "Veriden karar ve süreç faydası üretme; faydayı maliyet ve zamanında kullanımla birlikte değerlendirme. İlk üçü 3V, son ikisi eklenince 5V."], ["Analiz zinciri", "Toplama → temizleme/doğrulama → depolama → işleme/sorgulama → analiz → karar."], ["Araç eşleştirmesi", "Veri ambarı: yapısal analiz; text analytics: serbest metin; stream computing: akış; HDFS: dağıtık saklama; MapReduce: işi parçalayıp sonuç birleştirme."]], "remember": "HDFS saklama yapısıdır; MapReduce işleme modelidir. Çok miktarda yanlış veri, güvenilir sonuç demek değildir.", "vize": false, "details": [], "id": "review-103-5"}, {"chapter": 103, "index": 6, "title": "Veri kaynakları ve bulutla ilişki", "rows": [["Kaynaklar", "Telefon/tablet, GPS/GSM, RFID, akıllı sayaç, sensör, IP kamera, tıbbi cihaz, web logu, sosyal medya, gen dizileme, meteoroloji ve simülasyon."], ["Büyümenin nedenleri", "Yeni dijital kaynaklar ortaya çıkması + eski kayıtların sayısallaşması + daha ayrıntılı kullanıcı/işlem kaydı tutulması."], ["Bulutun katkısı", "Esnek hesaplama ve saklama, artan veri yükünü yönetmeye yardım eder. Büyük veri kurumun yerel altyapısında da işlenebilir."], ["Faydaya dönüşüm", "Maliyet azaltma, pazarlama, müşteri deneyimi, süreç verimi ve anormallik/güvenlik tespiti."]], "remember": "Her bulut işi büyük veri değildir; her büyük veri işi için bulut zorunlu değildir.", "vize": false, "details": [], "id": "review-103-6"}, {"chapter": 103, "index": 7, "title": "Büyük verinin 11 kullanım alanı", "rows": [["Bankacılık / sigorta", "Finansal suç ve olağandışı işlem, risk/uyum, çapraz satış; sigortada risk, fiyatlama ve müşteri kârlılığı."], ["Medya / perakende", "Öneri, içerik ve memnuniyet; perakendede müşteri–ürün–zaman–yer–kanal eksenleri, stok ve personel planı."], ["Sağlık / eğitim", "Hasta kayıtları, görüntü ve genetikten örüntü/erken tespit; öğrenme etkinlikleri, giriş/sayfa/süre kayıtlarından eğitim iyileştirme."], ["Üretim / enerji", "Sensör/alarmla arıza öncesi bakım; akıllı üretim; akıllı sayaçlarla tüketim/üretim ve tesis konumu planı."], ["Devlet / ulaşım", "İhtiyaç dağılımı, e-devlet, akıllı şehir; trafik/rota, sevkiyat, ambulans ve nakliye optimizasyonu."], ["Kendi kendine ölçüm", "Telefon/bileklikten hareket-egzersiz; niyet ile gerçek davranış farkını ölçme."], ["Notun kurum örnekleri", "Turkcell–Anadolu Jet, Avea Intellimap, Software AG Türkiye, Anadolu Bilişim; dünya örnekleri Amazon, Apple/iCloud, Google/App Engine, Microsoft/Azure, IBM/Blue Cloud, AT&T/Synaptic, Apache/Hadoop."]], "remember": "Veri paylaşımında gizlilik ve izin; analizde uygunluk, doğruluk ve amaca uygun kullanım gözetilir.", "vize": false, "details": [], "id": "review-103-7"}, {"chapter": 103, "index": 8, "title": "Sayısal örnekleri doğru yorumlama", "rows": [["Sayının anlattığı kavram", "Sensör akışının sıklığı hız; biriken TB/PB miktarı hacim; metin/görüntü/ölçüm karışımı çeşitliliktir."], ["Eski ve bağlamlı sayılar", "Notlarda farklı yıl, evren ve yuvarlamalar vardır. Örneğin yapısal olmayan veri için %95 ve %80 geçmesi tek evrensel oran bulunduğu anlamına gelmez."], ["Temel birimler", "KB → MB → GB → TB → PB → EB → ZB. Doktor notu ile tıbbi görüntünün ölçeği aynı değildir."]], "remember": "Bu bölümdeki sayılar geçmiş ders örnekleri/tahminleridir; bugünün dünya istatistiği olarak kullanılmaz.", "vize": false, "details": [["Hız örnekleri", "Facebook: günde 2,7 milyar beğeni/yorum; Twitter: dakikada 350 bin/günde 500 milyon tweet; WhatsApp: günde 50 milyar mesaj; e-posta: günde 200 milyardan fazla."], ["Sensör ve deney", "Jet: 30 dakikada 10 TB; Formula 1: 150 sensör/20 GB; CERN: saniyede 1 PB örnekleri. Bağlamları farklıdır."], ["Eski büyüme tahminleri", "2020 için 2009’un 44 katı/35 ZB; CSC atfıyla %4300 artış. IBM atfında 2014’te verinin %90’ı iki yılda üretilmiş ve günlük 2,5 EB; 2003’e kadar 5 EB, sonra iki günde aynı miktar anlatımı."], ["Gen ve pazar", "Gen dizileme: 1000 ABD dolarının altı ve onlarca TB. 2016 pazarı 130,1 milyar dolar; 2020 için %11,7 bileşik büyüme ve 203 milyar dolar üzeri tahmin."], ["2016 sektör dağılımı", "Bankacılık %13,1; kesikli üretim %11,9; süreç üretimi %8,4; devlet %7,6; profesyonel hizmetler %7,4."], ["Fotoğraf örneği", "Facebook: saniyede 4000; dakikada 243 bin; saatte 14,58 milyon; günde 350 milyon. Yaklaşık ve farklı yuvarlamalı değerler."], ["Sağlık ve sayaç", "Elektronik kayıt: 2005’te %30; 2011 hastane %75/doktor %45; 2013 hastane HIE katılımı yaklaşık %45. HIE: Health Information Exchanges. Sayaç: günde bir ölçüm yerine 15 dakikada bir ölçüm."]], "id": "review-103-8"}, {"chapter": 104, "index": 0, "title": "Bulut ortamları ve hizmet adları", "rows": [["Sağlayıcı / hizmet", "AWS bir hizmetler bütünüdür. EC2 hesaplama/VM; AMI VM imajı; S3 nesne depolama; SQS yazılım bileşenleri arası mesaj/görev kuyruğu; RDS ilişkisel veri tabanı; SimpleDB nottaki dağıtık veri tabanıdır."], ["Azure’un nottaki mimarisi", "Compute: Web/Worker Role; Storage: saklama; Fabric: kaynak ve işletim koordinasyonu. Virtual Machines, Web Sites ve Cloud Services farklı yönetim düzeylerini örnekler."], ["Platform örnekleri", "App Engine, Force.com, Heroku, AppScale, OrangeScape, Engine Yard ve OpenShift dersin PaaS/platform örnekleridir. AWS/Azure tek hizmet modeline indirgenemez."], ["Ayırt edici adlar", "Caspio: veri tabanı/az kodlu uygulama; Cloudify: açık kaynak hizmet odaklı platform; Nimbus: bilimsel/yoğun hesaplama IaaS; Eucalyptus: özel/karma IaaS."], ["Diğer tarihsel ortamlar", "Sun Cloud: Solaris/Grid Engine/Java; Vertebra: Ruby/Erlang; Rackspace: barındırma; Rollbase: sürükle-bırak/az kodlu uygulama."], ["Tarih düzeltmesi", "App Engine ilk önizlemesi 7 Nisan 2008’dir. SQS’nin ana işi insan sohbeti değil yazılım bileşenlerini kuyrukla ayırmaktır."]], "remember": "Ürün ve dil listeleri notun dönemine aittir; adları görevleriyle eşleştir.", "vize": true, "details": [], "id": "review-104-0"}, {"chapter": 104, "index": 1, "title": "Hizmet ve sağlayıcı seçimi", "rows": [["Başlangıç", "İş hedefi, kazanım, uygulama/veri gereksinimi, kullanıcı sayısı, kapasite, performans ve bütçe belirlenir; iş birimleri ve yönetim sürece katılır."], ["Sağlayıcı değerlendirmesi", "İtibar, deneyim, mali sağlamlık, uzmanlık, referans, destek, denetim, raporlama ve güvenlik."], ["Toplam ücret", "Birim fiyat + tahsis/tüketim + aktarım + depolama + lisans + destek. Faturanın açıklanabilir olması gerekir."], ["Teknik ve sözleşmesel uyum", "API/standartlar, mevcut sistemlerle entegrasyon, yükseltme, SLA, kapasite/kota, erişim, veri konumu ve alt yükleniciler."], ["Çıkış planı", "Veriyi hangi biçimde, sürede ve ücretle alacağın; sağlayıcı değişimi, silme, destek ve geri dönüş koşulları önceden belirlenir."]], "remember": "Yalnız en düşük fiyat veya fiziksel sunucu sayısıyla karar verilmez; ihtiyaca uygunluk ve çıkış da değerlendirilir.", "vize": false, "details": [], "id": "review-104-1"}, {"chapter": 104, "index": 2, "title": "Modellere göre işletim sorumluluğu", "rows": [["IaaS", "Müşteri OS, lisans/yama, ara yazılım, uygulama, performans ve rol/kota ayarlarını takip eder. Fiziksel altyapı sağlayıcıdadır."], ["PaaS", "Geliştirici kod, veri ve uygulama ayarlarına odaklanır; platform/OS işletimi sağlayıcıdadır. PHP uygulamasını temel web/SQL altyapısını kurmadan yayımlama örnektir."], ["SaaS", "Hazır ofis, ERP/KKP, İK ve CRM/MİY kullanılır. Salesforce, Google Apps, Webex ve GoToMeeting notun örnekleridir; kullanıcı/erişim kararları müşteride sürer."], ["Yönetim araçları", "Cloudyn, CloudHealth, RightScale Cloud Analytics dersin CMP örnekleridir; kullanım, kaynak ve maliyet görünürlüğünü destekler."]], "remember": "Boşta ama tahsisli kaynak ücretlenebilir. Her SaaS aynı yedek/ODM hizmetini veya her PaaS sınırsız taşınabilirliği sağlamaz.", "vize": false, "details": [], "id": "review-104-2"}, {"chapter": 104, "index": 3, "title": "Bulut yönetimi ve FCAPS", "rows": [["Yönetimin kapsamı", "Planlama, tasarım, sunum, işletim ve kontrol; hem bulutu yönetmek hem bulut araçlarıyla kurum içi kaynakları yönetmek."], ["FCAPS", "Fault: arıza; Configuration: yapılandırma; Accounting: kullanım/muhasebe; Performance: performans; Security: güvenlik."], ["İşler", "Kaynak tahsisi, yapılandırma, erişim/politika, performans, ölçüm ve optimizasyon; ağ, depolama, hesaplama ve uygulama verilerini birlikte izleme."], ["App Engine yönetim örnekleri", "Uygulama ve alan adı; ekip daveti; veri/hata logu; trafik; veri deposu ve indeks; zamanlanmış görev; test."], ["Ürün örnekleri", "BMC, Computer Associates, HP, Microsoft ve IBM Cloud Computing notun yönetim ürünü aileleridir."]], "remember": "Yavaşlıkta önce ağ, kod, veri tabanı ve kaynak ölçümlerini incele; rastgele kapasite büyütmek her sorunu çözmez.", "vize": false, "details": [], "id": "review-104-3"}, {"chapter": 104, "index": 4, "title": "Buluta geçişin 6 adımı", "rows": [["Sıra", "Strateji → mevcut mimari → aktarım planı → sağlayıcı seçimi → analiz/test → aktarma/yönetim."], ["Envanter", "Hizmet, uygulama, veri; sunum–iş mantığı–veri katmanları; boyut/biçim/ilişkiler, kritik işler, erişim, güvenlik ve bağımlılıklar."], ["Aktarım planı", "Ne, hangi sırayla, ne zaman ve kimin sorumluluğunda taşınacak; BT, iş birimi, yönetim, finans ve gerekli uzmanlar birlikte çalışır."], ["Üç yol", "Hazır bulut uygulamasına geçip veriyi taşıma; aynı işi platformda yeniden geliştirme; mevcut uygulamayı az değişiklikle taşıma (lift and shift)."], ["Standartlar", "OVF: VM paketleme/taşınabilirlik; OCCI: bulut altyapısı yönetim arayüzü; CDMI: bulut veri nesnelerine erişim ve yönetim arayüzü. CloudCmp karşılaştırma örneğidir."], ["Risk grupları", "Kurumsal: kapanma/bağımlılık/kesinti; teknik: altyapı/açık/veri hasarı; hukuki: kanıt/yetki/lisans; ortak: afet/yedek hatası/ifşa."], ["Pilot ve işletim", "Önce işlev, maliyet, ağ, SLA, güvenlik ve geri dönüş test edilir; kontrollü geçişten sonra izleme/iyileştirme sürer. Kurumun uygulaması, SaaS uygulaması ve sağlayıcının yönetim araçları ayrı değerlendirilir."]], "remember": "Geçiş yalnız dosya kopyalamak değildir; veri konumu, iletişim maliyeti, roller, eğitim ve çıkış planını da değiştirir.", "vize": false, "details": [], "id": "review-104-4"}, {"chapter": 104, "index": 5, "title": "SLA, kullanılabilirlik ve süreklilik", "rows": [["SLA", "Hizmet Düzeyi Anlaşması (Service Level Agreement); hizmet süresi, performans, tepki/arıza çözüm süresi, ölçüm, istisna ve ihlal karşılığını tanımlar. Sözleşme ayrıca fiyat, sorumluluk, fesih ve veri çıkışını düzenler."], ["Kullanılabilirlik", "Yetkilinin gereken zamanda hizmete erişebilmesi. Veri/kaynakların farklı arıza alanlarında yedekliliği, eşitleme ve geçiş mekanizması birlikte tasarlanır."], ["Instance / zone / region", "Instance çalışan sunucu örneği; zone bölge içindeki arıza alanı; region daha geniş coğrafi hizmet bölgesidir."], ["DNS ve TTL", "Aktif sistem arızalanınca yedeğe yönlendirme yapılabilir. TTL kaydın önbellek süresini etkiler; düşük TTL sıfır süreli/kayıpsız geçiş garantisi değildir."], ["Kota ve maliyet", "Kaynaklar sonsuz değildir; limit ve kapasite planı gerekir. Unutulan test VM’leri ve fazla tahsis gereksiz ücret oluşturur."], ["İşletim düzeni", "Kaynak sahibi/amacı/süresi belirlenir; sanallaştırma/entegrasyon, güvenli otomasyon–orkestrasyon, self-servis ve gerekirse hibrit/cloud bursting uygulanır. PoC ve belgeli süreç riski azaltır."]], "remember": "Tek VM’yi buluta taşımak kesintisizlik sağlamaz. Yedek kopya, yüksek kullanılabilirlik ve felaket kurtarma ayrı hedeflerdir.", "vize": true, "details": [], "id": "review-104-5"}, {"chapter": 104, "index": 6, "title": "Veri yaşam döngüsü ve yönetişim", "rows": [["Veri yönetimi / yönetişim", "Yönetim veriyi yaşamı boyunca işler, korur, taşır, arşivler ve siler. Yönetişim yetkiyi, sorumluluğu ve kuralları belirler."], ["Sınıflandırma", "Çok hassas, orta hassas ve hassas olmayan/genel; araştırma verisinde gizlilik sözü, sınırlı kullanım ve katılımcı korunması önemlidir."], ["Veri türleri", "Yapısal: tanımlı alanlar; yarı yapısal: XML/JSON; yapısal olmayan: serbest içerik. İsteğe bağlı bir alan tek başına yapısal olmayan veri demek değildir."], ["Bulut verisinin özellikleri", "Büyüyen hacim, olası dağıtık saklama, ağ/gecikme, maliyet, kimlik/yetki ve gizlilik ayarları. Her veri mutlaka kurum dışında veya herkesçe erişilebilir değildir."], ["Taşınabilirlik", "Uygulama ve verinin anlam/biçim korunarak az değişiklikle başka ortama aktarılması. Açık biçim, standart API ve dışa aktarma testi satıcı bağımlılığını azaltır."]], "remember": "Depolama yaşam döngüsünün yalnız bir parçasıdır; politika olmadan her veriyi buluta taşımak doğru yönetim değildir.", "vize": false, "details": [], "id": "review-104-6"}, {"chapter": 104, "index": 7, "title": "Gizlilik, bütünlük, erişilebilirlik", "rows": [["Gizlilik / confidentiality", "Veriyi yalnız yetkili okuyabilsin; şifreleme, izinler ve anahtar yönetimi destekler."], ["Bütünlük / integrity", "Veri istenmeden/yetkisiz değiştirilmesin; doğrulama, yetki ve değişiklik kayıtları destekler. Integrity “şeffaflık” değildir."], ["Erişilebilirlik / availability", "Yetkili kullanıcı ihtiyaç anında veriye/hizmete ulaşabilsin; yedeklilik ve süreklilik planı destekler."], ["Kimlik ve kayıt", "Kimlik doğrulama kullanıcıyı; yetkilendirme yapabileceklerini belirler. Giriş, başarısız deneme ve kritik değişiklikler loglanır."], ["Şifreleme", "Depolanan ve aktarılan veri için düşünülür; anahtarı kimin tuttuğu ve çözebildiği önemlidir. Sunucu tarafı şifreleme sağlayıcının asla çözemeyeceğini garanti etmez."], ["Şifreli sorgu", "İndeks/arama tasarımı gizlilik sızıntısı ve ek işlem maliyetiyle birlikte değerlendirilir. Yalnız tüm erişimi kapatmak güvenliğin üç hedefini birden karşılamaz."]], "remember": "Okunma → gizlilik; değiştirilme → bütünlük; ulaşılamama → erişilebilirlik.", "vize": false, "details": [], "id": "review-104-7"}, {"chapter": 104, "index": 8, "title": "SQL, NoSQL ve sorgu performansı", "rows": [["İlişkisel veri tabanı", "Tanımlı şema, ilişkili tablolar ve SQL. Oracle, DB2, SQL Server, PostgreSQL, MySQL örnekleridir."], ["NoSQL", "Not only SQL: belge, anahtar-değer, geniş sütun ve grafik aileleri. Hepsi bellekte çalışmaz; tek ortak sorgu dili veya her durumda daha hızlı olma kuralı yoktur."], ["İşlemler", "SELECT: oku/sorgula; INSERT: ekle; UPDATE: değiştir; DELETE: sil. Okuma-yazma yükü ve indeks bakımı maliyet yaratır."], ["Performans", "Sorgu planı, indeks, veri modeli, bölümleme, paralellik, sonuç kümesi, ağ/gecikme ve tutarlılık gereksinimi birlikte değerlendirilir."], ["Dağıtık saklama", "Makine hızı, ağ, kopyalar ve arıza sorguyu etkiler. Hız, doğruluk/tutarlılık ve kaynak tüketimi birlikte dengelenir."]], "remember": "SQL büyük veride de kullanılabilir; ilişkisel sistemler JSON da saklayabilir. Veri modeli seçimi iş yüküne bağlıdır.", "vize": false, "details": [], "id": "review-104-8"}, {"chapter": 104, "index": 9, "title": "Sıkıştırma, yedekleme ve geri yükleme", "rows": [["Sıkıştırma / şifreleme", "Sıkıştırma boyut ve ağ/disk aktarımını azaltır; şifreleme gizlilik sağlar. Amaçları farklıdır."], ["Kayıpsız / kayıplı", "Kayıpsız özgün veriyi geri getirir; kayıplı bazı ayrıntılardan vazgeçer. Önceden sıkışmış fotoğraf/video ek sıkıştırmada az kazandırabilir."], ["İşlem maliyeti", "Alan/aktarım tasarrufu karşılığında CPU, bellek ve gecikme oluşabilir; iki uç biçimi/algoritmayı desteklemelidir."], ["Yedek planı", "Neyi, nerede, hangi araçla, ne sıklıkla, tam/artımlı hangi yöntemle, ne kadar saklayarak ve hangi geri yükleme testiyle koruyacağını belirle."], ["Eşitleme / çoğaltma / yedek", "Eşitleme değişikliği yayar; replikasyon kopyayı sürdürür; ayrı/sürümlü yedek önceki duruma döndürür. Yanlış silme ilk ikisine de yayılabilir."]], "remember": "Yedek almak yetmez; geri yüklenebilir olduğunu test etmek gerekir.", "vize": false, "details": [], "id": "review-104-9"}, {"chapter": 104, "index": 10, "title": "OAuth, SAML ve IDaaS", "rows": [["Kimlik doğrulama / yetkilendirme", "Kimlik doğrulama hesabın kimliğini; yetkilendirme erişim kapsamını belirler."], ["OAuth", "Kaynak sahibinin parolasını başka uygulamaya vermeden, token ile sınırlı/süreli kaynak erişimi yetkisi devretme çerçevesidir. Tek başına kimlik doğrulama protokolü değildir."], ["SAML", "XML tabanlı güvenlik bildirimlerini kimlik sağlayıcı (IdP) ile hizmet sağlayıcı (SP) arasında taşır; kurumsal tek oturum açma (SSO) örneğidir."], ["IDaaS", "Kimlik yönetimi işlevlerinin hizmet olarak sunulmasıdır; protokol adıyla hizmet modelini ayır."]], "remember": "OAuth: yetki devri. SAML: kimlik/güvenlik bildirimi. IDaaS: yönetilen kimlik hizmeti.", "vize": false, "details": [], "id": "review-104-10"}, {"chapter": 104, "index": 11, "title": "Güvenlik katmanları ve veri izolasyonu", "rows": [["Fiziksel güvenlik", "Veri merkezine erişim, donanım, güç ve çevre koruması."], ["Ağ güvenliği", "Trafik kontrolü, güvenli yapılandırma, segmentasyon, saldırı tespiti ve dayanıklılık."], ["Platform bütünlüğü", "OS ve hipervizörün güvenli/güncel kalması. Kimlik yönetimi ise hesap, doğrulama ve yetkileri kapsar."], ["Veri izolasyonu ve silme", "Ortak fiziksel kaynakta kiracılar ayrılmalıdır; yeniden tahsis edilen diskte veri kalıntısı güvenli biçimde silinmelidir."]], "remember": "Geçici kesinti güvenlik katmanı değil olaydır. Yetkisiz veri silme saldırı; kurallı temizleme/bertaraf meşru işlemdir.", "vize": false, "details": [], "id": "review-104-11"}, {"chapter": 104, "index": 12, "title": "Sanal ortamlara yönelik tehditler", "rows": [["VM escape", "Konuk sistemin izolasyon sınırını aşıp hipervizör/host’a ulaşması."], ["Cross-VM", "Ortak fiziksel kaynaktaki başka VM’yi hedefleme veya yan kanalla bilgi çıkarma."], ["Güvensiz VM göçü", "Taşınan bellek/durum ve kontrol trafiğinin gizlilik/bütünlüğünün bozulması."], ["Önlemler", "Hipervizör/guest yamaları, en az yetki, kiracı izolasyonu, ayrı yönetim ağı, güçlü doğrulama, korumalı taşıma kanalı ve olay izleme."]], "remember": "VM kaçışı normal VM taşıma işlemi değildir.", "vize": false, "details": [], "id": "review-104-12"}, {"chapter": 104, "index": 13, "title": "DoS, DDoS, botnet ve savunma", "rows": [["DoS / DDoS", "Hizmeti kullanılamaz kılma; çok sayıda dağıtık kaynaktan geliyorsa DDoS."], ["Botnet", "Saldırganın ele geçirdiği cihaz ağı; DDoS, spam veya başka kötü amaçlı işler için kullanılabilir. Saldırı türüyle cihaz ağını ayır."], ["Tespit yöntemleri", "Activity Profiling: normal profilden sapma; Changepoint Detection: ani trafik değişimi; Wavelet-based Signal Analysis: farklı zaman ölçeklerinde örüntü; Identify Scan Activity: tarama davranışı."], ["Savunma", "Trafik süzme, hız sınırlama, kötü kaynağı ayırma, DDoS koruma, güvenli yapılandırma, yedeklilik ve izleme. Disabling Handlers saldırı kontrol bileşenlerini etkisizleştirmedir; tespit yöntemi değildir."], ["IDS / IPS", "IDS şüpheli olayı tespit eder; IPS uygun kurallarla engelleme de yapabilir."]], "remember": "Yalnız sunucu eklemek her DDoS’u çözmez; tespit yöntemi ile savunma eylemi farklıdır.", "vize": false, "details": [], "id": "review-104-13"}, {"chapter": 104, "index": 14, "title": "Saldırı–etki–önlem eşleştirmesi", "rows": [["Kimlik avı / hesap hırsızlığı", "Hesabı hedefler → MFA, güçlü doğrulama, farkındalık, kısıtlı erişim."], ["Veri sızıntısı", "Gizliliği bozar → doğru izin, şifreleme, anahtar yönetimi, denetim."], ["Yetkisiz silme / tahrip", "Bütünlük ve erişilebilirliği bozar → yetki, değişiklik kaydı, ayrı/sürümlü yedek ve geri yükleme testi."], ["Sanal ağların kandırılması", "Sahte ağ/kimlik veya trafik yönlendirmesi → ağ ayrımı, doğrulama, korumalı iletişim."]], "remember": "Bir tehdidi adı, etkilediği güvenlik hedefi ve uygun önlemiyle birlikte hatırla.", "vize": false, "details": [], "id": "review-104-14"}, {"chapter": 104, "index": 15, "title": "Standartlar ve kuruluşlar", "rows": [["NIST", "Bulut tanımı ve teknik rehberler."], ["CSA / OCC", "Cloud Security Alliance: bulut güvenliği rehberleri/çerçeveleri. Open Cloud Consortium: bulut ekosistemi çalışmaları."], ["SNIA / ISO / TSE", "SNIA: depolama endüstrisi standartları; ISO: uluslararası standardizasyon; TSE: Türkiye’de standardizasyon."], ["Sınav terminolojisi", "Notlardaki benzer kuruluş adlarını doğru adlarıyla ayır. Hepsinin hukukî niteliği veya standart belirleme görevi aynı değildir."]], "remember": "Tek bir kuruluşun Türkiye’deki bütün siber güvenlik yetkilerini tek başına taşıdığı sonucunu çıkarma.", "vize": false, "details": [], "id": "review-104-15"}, {"chapter": 104, "index": 16, "title": "Sözleşme ve hizmet taahhüdü", "rows": [["Sözleşmenin kapsamı", "Hizmet, ücret, veri konumu, gizlilik/bütünlük, sorumluluk, değişiklik, fesih/çıkış ve uygulanacak hukuk/yetki gibi şartlar."], ["SLA ayrımı", "SLA ölçülebilir hizmet seviyesi, ölçüm ve istisnaları düzenler; otomatik sıfır kesinti garantisi değildir."], ["Tarihsel hukuk terimi", "Tüketiciye karşı gerekli özen eksikliğindeki sorumluluğu sınırlayan hüküm bağlamında notların beklediği terim “haksız şart”tır."], ["Sınıflandırma notu", "Mahkeme celbi/e-keşif, notlardaki sözleşme aşamaları sınıflandırmasının dışında ele alınır. Bunlar dersin tarihsel terminolojisidir."]], "remember": "SLA hizmet seviyesini; genel sözleşme daha geniş ilişki ve sorumlulukları düzenler.", "vize": false, "details": [], "id": "review-104-16"}, {"chapter": 104, "index": 17, "title": "Mobil bulut ve Azure model örnekleri", "rows": [["Mobil bulut", "Hesaplamayı uzağa devretme kaynak paylaşımı/esneklik ve bazı işlerde pil/ekonomi yararı sağlayabilir. Bağlantı, gecikme ve aktarım enerjisi de hesaba katılır."], ["Birlikte değerlendirilenler", "Altyapı + bütünleştirme + güvenlik."], ["PaaS örneği", "Azure App Service + Azure SQL Database: yönetilen uygulama/veri tabanı platformu. Azure Cosmos DB de yönetilen veri tabanı platform hizmetidir."], ["IaaS ayrımı", "Azure VM’de kendi web sunucunu/OS’ni işletmen IaaS’tır. Azure adı tek başına hizmet modelini belirlemez."]], "remember": "Hazır platforma kod dağıtmak PaaS; VM/OS yönetmek IaaS; hazır uygulamayı kullanmak SaaS.", "vize": true, "details": [], "id": "review-104-17"}];
